package apidocs

func (d *document) faculties() {
	d.op("Faculties", "GET", "/api/v1/faculties", "List faculties for forms and administration", staffReaders, "FacultyPage", 200).paging(100000).query("active", enumeration("true", "false", "all"), "Default true: active choices only. False returns inactive faculties; all returns both for administration and historical filters.").note("Ordered by case-insensitive name then faculty_id. Use returned current name in existing Student and announcement faculty fields. No request body.")
	d.op("Faculties", "GET", "/api/v1/faculties/{facultyID}", "Get faculty including inactive state", staffReaders, "Faculty", 200).note("Stable identity is preserved across rename, deactivation and activation.")
	d.op("Faculties", "POST", "/api/v1/faculties", "Create active faculty", admin, "Faculty", 201).body("FacultyDetails").fail(413, "").fail(409, "faculty_name_conflict: current and historical names are case-insensitively reserved.").note("JSON name only, maximum 8 KiB. Duplicate names conflict; check the catalogue after an uncertain create response rather than creating another name.")
	d.op("Faculties", "PATCH", "/api/v1/faculties/{facultyID}", "Rename faculty without replacing its identity", admin, "Faculty", 200).body("FacultyDetails").fail(413, "").fail(409, "faculty_name_conflict: another faculty owns this current or historical name.").note("JSON name only. Updates existing Student faculty labels, including archived profiles. Old announcements retain their original name snapshot and remain associated with the same audience identity. Old names remain reserved and are not selectable for new registrations/publications. Exact same-name retry is a no-op.")
	d.op("Faculties", "POST", "/api/v1/faculties/{facultyID}/deactivate", "Deactivate faculty for new registrations and notices", admin, "Faculty", 200).note("Empty body and no query. Existing Student assignments, profile edits and historical announcement/inbox visibility remain. New assignments, invitation/CSV registrations and new faculty-targeted publications are rejected. Exact prior invitation/publication retries remain readable. Repeat deactivation is a no-op with no duplicate audit entry.")
	d.op("Faculties", "POST", "/api/v1/faculties/{facultyID}/activate", "Reactivate the same faculty", admin, "Faculty", 200).note("Empty body and no query. Preserves faculty_id, existing Students and history; makes the current name selectable again. Repeat activation is a no-op. No delete endpoint.")
}
